use super::{fs, StreamFlags};

/// A host-scoped FSEvents journal cursor.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct FsEventCursor(fs::FSEventStreamEventId);

impl FsEventCursor {
    /// Capture the most recent event identifier generated by the host.
    ///
    /// Events may be generated immediately after this call. Starting a stream
    /// from the returned cursor replays those later events before `HistoryDone`.
    pub fn current_safe() -> Self {
        Self(unsafe { fs::FSEventsGetCurrentEventId() })
    }

    /// Construct a cursor from a native FSEvents event identifier.
    pub const fn from_raw(value: u64) -> Self {
        Self(value)
    }

    /// Return the native event identifier carried by this cursor.
    pub const fn get(self) -> u64 {
        self.0
    }
}

/// Coverage-relevant flags attached to one FSEvents journal record.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct FsEventCoverageFlags {
    bits: u32,
}

impl FsEventCoverageFlags {
    pub(super) fn from_stream_flags(flags: StreamFlags) -> Self {
        Self { bits: flags.bits() }
    }

    /// Construct flags from the bitset supplied by CoreServices.
    pub const fn from_raw(bits: u32) -> Self {
        Self { bits }
    }

    /// Return the native CoreServices bitset.
    pub const fn get(self) -> u32 {
        self.bits
    }

    /// Whether descendants must be scanned because FSEvents coalesced detail.
    pub const fn must_scan_subdirs(self) -> bool {
        self.bits & fs::kFSEventStreamEventFlagMustScanSubDirs != 0
    }

    /// Whether user-space delivery dropped journal history.
    pub const fn user_dropped(self) -> bool {
        self.bits & fs::kFSEventStreamEventFlagUserDropped != 0
    }

    /// Whether the kernel dropped journal history.
    pub const fn kernel_dropped(self) -> bool {
        self.bits & fs::kFSEventStreamEventFlagKernelDropped != 0
    }

    /// Whether the host's FSEvents identifiers wrapped.
    pub const fn ids_wrapped(self) -> bool {
        self.bits & fs::kFSEventStreamEventFlagEventIdsWrapped != 0
    }

    /// Whether this record terminates replay of historical events.
    pub const fn history_done(self) -> bool {
        self.bits & fs::kFSEventStreamEventFlagHistoryDone != 0
    }

    /// Whether the watched root or one of its ancestors moved or disappeared.
    pub const fn root_changed(self) -> bool {
        self.bits & fs::kFSEventStreamEventFlagRootChanged != 0
    }
}

/// One coverage observation from the native FSEvents stream.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FsEventCoverageEvent {
    cursor: FsEventCursor,
    flags: FsEventCoverageFlags,
}

impl FsEventCoverageEvent {
    /// Construct a coverage observation from native callback fields.
    pub const fn new(cursor: FsEventCursor, flags: FsEventCoverageFlags) -> Self {
        Self { cursor, flags }
    }

    /// The journal cursor delivered with this native record.
    pub const fn cursor(self) -> FsEventCursor {
        self.cursor
    }

    /// The coverage-relevant flags delivered with this native record.
    pub const fn flags(self) -> FsEventCoverageFlags {
        self.flags
    }
}

/// Lifecycle and journal observations emitted on the native control lane.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FsEventCoverageSignal {
    /// The native stream was created and started successfully.
    Started,
    /// A native journal record was delivered.
    Event(FsEventCoverageEvent),
    /// The native stream stopped and will deliver no further records.
    Stopped,
}

/// Receives FSEvents control observations independently from translated events.
pub trait FsEventCoverageHandler: Send + 'static {
    /// Handle one native stream observation.
    fn handle_coverage(&mut self, signal: FsEventCoverageSignal);
}

impl<F> FsEventCoverageHandler for F
where
    F: FnMut(FsEventCoverageSignal) + Send + 'static,
{
    fn handle_coverage(&mut self, signal: FsEventCoverageSignal) {
        (self)(signal);
    }
}
